import { viewCoverImage } from './viewCoverImage.js';

// The image determines the mount. The border is a physical inset on every side.
export function exhibitionImageSize(sourceWidth, sourceHeight, maxWidth, maxHeight, border = .03) {
  const ratio = sourceWidth > 0 && sourceHeight > 0 ? sourceWidth / sourceHeight : maxWidth / maxHeight;
  const width = Math.min(maxWidth, maxHeight * ratio);
  const height = width / ratio;
  return { width, height, outerWidth: width + border * 2, outerHeight: height + border * 2 };
}

const decodedImages=new Map(),displayImages=new Map(),imageQueue=[];
const warmingImages=new Map();
const warmingQueue=[];
let activeWarmers=0;
export function warmExhibitionImages(sources,{maxDimension=384}={}) {
  const work=[...new Set(sources.filter(Boolean))].map(source=>{
    const key=`${source}|${maxDimension}`;
    if(warmingImages.has(key))return warmingImages.get(key);
    const result=new Promise(resolve=>{warmingQueue.push({source,maxDimension,resolve});});
    warmingImages.set(key,result);return result;
  });
  function next(){
    while(activeWarmers<2&&warmingQueue.length){
      const job=warmingQueue.shift();activeWarmers++;
      preloadExhibitionImage(job.source,{maxDimension:job.maxDimension,priority:'low'}).catch(()=>{
        warmingImages.delete(`${job.source}|${job.maxDimension}`);
      }).finally(()=>{warmingImages.delete(`${job.source}|${job.maxDimension}`);activeWarmers--;job.resolve();next();});
    }
  }
  next();return Promise.all(work);
}
let activeImages=0;
function nextImage(){
  while(activeImages<4&&imageQueue.length){
    const job=imageQueue.shift();activeImages++;
    job().finally(()=>{activeImages--;nextImage();});
  }
}

// Keep the decoded HTML image alive as well as its ImageBitmap. The Hall uses
// the bitmap for Three.js, while the collection preview uses the HTML image.
// Retaining both prevents the preview panel from decoding the same illustration
// again when it first appears.
export function preloadExhibitionImage(source,{maxDimension=1024,priority='auto'}={}){
  const resolved=viewCoverImage(source,maxDimension);
  const url=new URL(resolved,window.location.href).href;
  if(displayImages.has(url))return displayImages.get(url);
  const result=(async()=>{
    const image=new Image();image.crossOrigin='anonymous';image.decoding='async';image.fetchPriority=priority;image.src=url;
    if(typeof image.decode==='function')await image.decode();
    else await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;});
    return image;
  })().catch(error=>{displayImages.delete(url);if(resolved!==source)return preloadExhibitionImage(new URL(source,window.location.href).href,{maxDimension:0,priority});throw error;});
  displayImages.set(url,result);
  if(displayImages.size>40)displayImages.delete(displayImages.keys().next().value);
  return result;
}

// Share decoded pixels across the hall, its preview and an individual visit.
// GPU textures still belong to their renderer and are disposed with the scene.
export function loadExhibitionImage(source,{maxDimension=1024}={}){
  const url=new URL(viewCoverImage(source,maxDimension),window.location.href).href;
  const key=`${url}|${maxDimension}`;
  if(decodedImages.has(key))return decodedImages.get(key);
  const result=new Promise((resolve,reject)=>{
    imageQueue.push(async()=>{
      try{
        let image=[...document.images].find(item=>item.complete&&item.naturalWidth&&(item.currentSrc||item.src)===url&&(item.crossOrigin==='anonymous'||new URL(url).origin===window.location.origin));
        if(!image)image=await preloadExhibitionImage(source,{maxDimension});
        const scale=Math.min(1,maxDimension/Math.max(image.naturalWidth,image.naturalHeight));
        let pixels=image;
        if(typeof createImageBitmap==='function'){
          try{pixels=await createImageBitmap(image,{imageOrientation:'flipY',premultiplyAlpha:'none',resizeWidth:Math.max(1,Math.round(image.naturalWidth*scale)),resizeHeight:Math.max(1,Math.round(image.naturalHeight*scale)),resizeQuality:'high'});}catch{ /* The decoded image remains a valid texture source. */ }
        }
        resolve(pixels);
      }catch(error){decodedImages.delete(key);reject(error);}
    });
  });
  decodedImages.set(key,result);
  if(decodedImages.size>16)decodedImages.delete(decodedImages.keys().next().value);
  nextImage();return result;
}
